import{_t as e,it as t,n,rt as r}from"./chunks/framework.wyZghjns.js";var i=JSON.parse(`{"title":"Interface: Goal","description":"","frontmatter":{},"headers":[],"relativePath":"api/@jsprismarine/prismarine/interfaces/Goal.md","filePath":"api/@jsprismarine/prismarine/interfaces/Goal.md"}`),a={name:`api/@jsprismarine/prismarine/interfaces/Goal.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<p><a href="./../../../">JSPrismarine</a> / <a href="./../">@jsprismarine/prismarine</a> / Goal</p><h1 id="interface-goal" tabindex="-1">Interface: Goal <a class="header-anchor" href="#interface-goal" aria-label="Permalink to “Interface: Goal”">​</a></h1><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/0b3d957d581dde17187e8dbf6703a396d3ef5483/packages/prismarine/src/entity/ai/Goal.ts#L11" target="_blank" rel="noreferrer">packages/prismarine/src/entity/ai/Goal.ts:11</a></p><p>One thing a mob might want to be doing.</p><p>Behavior is built out of small independent goals rather than one big state machine per mob, because the things a mob does overlap: it wanders, and it looks at you, and it panics when hurt, and those are three separate concerns that a state machine would have to enumerate the product of. A goal only has to answer &quot;would I like to run&quot; and &quot;am I still going&quot;.</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h2><h3 id="lanes" tabindex="-1">lanes <a class="header-anchor" href="#lanes" aria-label="Permalink to “lanes”">​</a></h3><blockquote><p><code>readonly</code> <strong>lanes</strong>: readonly <a href="./../enumerations/GoalLane.html"><code>GoalLane</code></a>[]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/0b3d957d581dde17187e8dbf6703a396d3ef5483/packages/prismarine/src/entity/ai/Goal.ts#L27" target="_blank" rel="noreferrer">packages/prismarine/src/entity/ai/Goal.ts:27</a></p><p>Which parts of the mob this goal drives - see <a href="./../enumerations/GoalLane.html">GoalLane</a>.</p><p>Two goals can run at once as long as they want different parts: strolling moves the legs, watching a player turns the head, and there is no reason a mob cannot do both.</p><hr><h3 id="name" tabindex="-1">name <a class="header-anchor" href="#name" aria-label="Permalink to “name”">​</a></h3><blockquote><p><code>readonly</code> <strong>name</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/0b3d957d581dde17187e8dbf6703a396d3ef5483/packages/prismarine/src/entity/ai/Goal.ts#L13" target="_blank" rel="noreferrer">packages/prismarine/src/entity/ai/Goal.ts:13</a></p><p>Used in logs and tests.</p><hr><h3 id="priority" tabindex="-1">priority <a class="header-anchor" href="#priority" aria-label="Permalink to “priority”">​</a></h3><blockquote><p><code>readonly</code> <strong>priority</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/0b3d957d581dde17187e8dbf6703a396d3ef5483/packages/prismarine/src/entity/ai/Goal.ts#L19" target="_blank" rel="noreferrer">packages/prismarine/src/entity/ai/Goal.ts:19</a></p><p>Lower runs first, and a running goal blocks every higher number that shares a lane with it. Panicking is 0; standing around looking at things is 6.</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="cancontinue" tabindex="-1">canContinue()? <a class="header-anchor" href="#cancontinue" aria-label="Permalink to “canContinue()?”">​</a></h3><blockquote><p><code>optional</code> <strong>canContinue</strong>(<code>mob</code>): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/0b3d957d581dde17187e8dbf6703a396d3ef5483/packages/prismarine/src/entity/ai/Goal.ts#L33" target="_blank" rel="noreferrer">packages/prismarine/src/entity/ai/Goal.ts:33</a></p><p>Whether a running goal wants to keep going. Defaults to <a href="#canuse">canUse</a> when absent.</p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="mob" tabindex="-1">mob <a class="header-anchor" href="#mob" aria-label="Permalink to “mob”">​</a></h5><p><a href="./../classes/Mob.html"><code>Mob</code></a></p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><hr><h3 id="canuse" tabindex="-1">canUse() <a class="header-anchor" href="#canuse" aria-label="Permalink to “canUse()”">​</a></h3><blockquote><p><strong>canUse</strong>(<code>mob</code>): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/0b3d957d581dde17187e8dbf6703a396d3ef5483/packages/prismarine/src/entity/ai/Goal.ts#L30" target="_blank" rel="noreferrer">packages/prismarine/src/entity/ai/Goal.ts:30</a></p><p>Whether this goal wants to start now. Called only while the goal is not running.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="mob-1" tabindex="-1">mob <a class="header-anchor" href="#mob-1" aria-label="Permalink to “mob”">​</a></h5><p><a href="./../classes/Mob.html"><code>Mob</code></a></p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><hr><h3 id="start" tabindex="-1">start()? <a class="header-anchor" href="#start" aria-label="Permalink to “start()?”">​</a></h3><blockquote><p><code>optional</code> <strong>start</strong>(<code>mob</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/0b3d957d581dde17187e8dbf6703a396d3ef5483/packages/prismarine/src/entity/ai/Goal.ts#L35" target="_blank" rel="noreferrer">packages/prismarine/src/entity/ai/Goal.ts:35</a></p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="mob-2" tabindex="-1">mob <a class="header-anchor" href="#mob-2" aria-label="Permalink to “mob”">​</a></h5><p><a href="./../classes/Mob.html"><code>Mob</code></a></p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="stop" tabindex="-1">stop()? <a class="header-anchor" href="#stop" aria-label="Permalink to “stop()?”">​</a></h3><blockquote><p><code>optional</code> <strong>stop</strong>(<code>mob</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/0b3d957d581dde17187e8dbf6703a396d3ef5483/packages/prismarine/src/entity/ai/Goal.ts#L36" target="_blank" rel="noreferrer">packages/prismarine/src/entity/ai/Goal.ts:36</a></p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="mob-3" tabindex="-1">mob <a class="header-anchor" href="#mob-3" aria-label="Permalink to “mob”">​</a></h5><p><a href="./../classes/Mob.html"><code>Mob</code></a></p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="tick" tabindex="-1">tick() <a class="header-anchor" href="#tick" aria-label="Permalink to “tick()”">​</a></h3><blockquote><p><strong>tick</strong>(<code>mob</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/0b3d957d581dde17187e8dbf6703a396d3ef5483/packages/prismarine/src/entity/ai/Goal.ts#L39" target="_blank" rel="noreferrer">packages/prismarine/src/entity/ai/Goal.ts:39</a></p><p>Called once per tick while the goal is running.</p><h4 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="mob-4" tabindex="-1">mob <a class="header-anchor" href="#mob-4" aria-label="Permalink to “mob”">​</a></h5><p><a href="./../classes/Mob.html"><code>Mob</code></a></p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p>`,69)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};